/**
 * FixtureDataset: the shape of a frozen sample dataset in apps/web/lib/fixtures/v2/.
 *
 * `provenance` can only be "fixture", so a fixture can never pass for a measurement. `engine_derived`
 * lists, as JSON pointers, the values FACTS marks ENGINE-DERIVED: they were chosen for the fixture and
 * are regenerated by the engine at CC-19. `withheld` states which collections hold a subset of a
 * check's records, and how many the check really had.
 */
import { z } from 'zod';
import { AccessTestSchema } from './access-test.js';
import { AccountSchema } from './account.js';
import { AlertRuleSchema } from './alert-rule.js';
import { ChangeSchema } from './change.js';
import { CheckSchema } from './check.js';
import { CountSchema, IdSchema, TimestampSchema } from './common.js';
import { WithheldCollectionSchema } from './enums.js';
import { FixEventSchema } from './fix-event.js';
import { FixSchema } from './fix.js';
import { LinkEdgeSchema } from './link-edge.js';
import { PageResultSchema } from './page-result.js';
import { ReportSchema } from './report.js';
import { SeatSchema } from './seat.js';
import { SiteSchema } from './site.js';

export const FixtureDatasetSchema = z.strictObject({
  provenance: z.literal('fixture'),
  /** The fixture's "now". */
  as_of: TimestampSchema,
  description: z.string().min(1),
  engine_derived: z.array(z.string().regex(/^(?:\/[^/]*)+$/)),
  accounts: z.array(AccountSchema),
  seats: z.array(SeatSchema),
  sites: z.array(SiteSchema),
  checks: z.array(CheckSchema),
  page_results: z.array(PageResultSchema),
  link_edges: z.array(LinkEdgeSchema),
  access_tests: z.array(AccessTestSchema),
  fixes: z.array(FixSchema),
  fix_events: z.array(FixEventSchema),
  changes: z.array(ChangeSchema),
  alert_rules: z.array(AlertRuleSchema),
  reports: z.array(ReportSchema),
  withheld: z.array(
    z.strictObject({
      check_id: IdSchema,
      collection: WithheldCollectionSchema,
      included: CountSchema,
      total: CountSchema,
    }),
  ),
});

export type FixtureDataset = z.infer<typeof FixtureDatasetSchema>;
